package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
)

const maxBodySize = 1048576 // 1MB

type RequestContext struct {
	Body    []byte
	Headers map[string]string
	Method  string
	Path    string
}

type APIResponse struct {
	Status  string      `json:"status"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

func verifyHMAC(message, signature, secret []byte) bool {
	if len(secret) == 0 {
		return false
	}
	mac := hmac.New(sha256.New, secret)
	mac.Write(message)
	expected := mac.Sum(nil)
	return hmac.Equal(expected, signature)
}

func sanitizeInput(input string) string {
	// Remove potentially dangerous characters for logging
	replacer := strings.NewReplacer("\n", " ", "\r", " ", "\t", " ")
	return replacer.Replace(input)
}

func parseContentLength(r *http.Request) int32 {
	clHeader := r.Header.Get("Content-Length")
	if clHeader == "" {
		return 0
	}
	val, err := strconv.ParseInt(clHeader, 10, 64)
	if err != nil {
		return 0
	}
	// Convert to working size type for buffer allocation
	return int32(val)
}

func readRequestBody(r *http.Request) ([]byte, error) {
	size := parseContentLength(r)

	// Validate size is within acceptable bounds
	if size <= 0 {
		// Fall back to streaming read with limit
		return io.ReadAll(io.LimitReader(r.Body, maxBodySize))
	}

	if size > maxBodySize {
		return nil, fmt.Errorf("request body too large: %d bytes", size)
	}

	// Pre-allocate buffer of exact size for efficiency
	buf := make([]byte, size)
	_, err := io.ReadFull(r.Body, buf)
	if err != nil {
		return nil, fmt.Errorf("error reading body: %w", err)
	}
	return buf, nil
}

func buildContext(r *http.Request, body []byte) *RequestContext {
	headers := make(map[string]string)
	for key := range r.Header {
		headers[key] = r.Header.Get(key)
	}
	return &RequestContext{
		Body:    body,
		Headers: headers,
		Method:  r.Method,
		Path:    r.URL.Path,
	}
}

func processWebhook(ctx *RequestContext) (*APIResponse, error) {
	secret := os.Getenv("WEBHOOK_SECRET")
	sigHeader, ok := ctx.Headers["X-Signature"]
	if !ok || sigHeader == "" {
		return nil, fmt.Errorf("missing signature")
	}

	sig, err := hex.DecodeString(sigHeader)
	if err != nil {
		return nil, fmt.Errorf("invalid signature format")
	}

	if !verifyHMAC(ctx.Body, sig, []byte(secret)) {
		return nil, fmt.Errorf("signature verification failed")
	}

	var payload map[string]interface{}
	if err := json.Unmarshal(ctx.Body, &payload); err != nil {
		return nil, fmt.Errorf("invalid JSON payload")
	}

	action, _ := payload["action"].(string)
	log.Printf("Processing webhook action: %s", sanitizeInput(action))

	return &APIResponse{
		Status:  "ok",
		Message: fmt.Sprintf("Processed action: %s", action),
		Data:    payload,
	}, nil
}

func webhookHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := readRequestBody(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	ctx := buildContext(r, body)
	resp, err := processWebhook(ctx)
	if err != nil {
		http.Error(w, err.Error(), http.StatusUnauthorized)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "healthy"})
}

func main() {
	http.HandleFunc("/webhook", webhookHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Server starting on port %s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
